"""Prepare a verified immutable block for Git object publication, no network writes."""
import base64,gzip,hashlib,json,sys
from pathlib import Path
p=Path(sys.argv[1]).resolve();idx=int(sys.argv[2]);assert 1<=idx<=9;name=f'block-{idx:03}';local=p/'checkpoints';meta=json.loads((local/(name+'.json')).read_text());audit=json.loads((local/(name+'.audit.json')).read_text());m=json.loads((p/'manifest.json').read_text());raw=(local/(name+'.json.gz')).read_bytes();decoded=gzip.decompress(raw).decode();cp=json.loads(decoded);sha=lambda b:hashlib.sha256(b).hexdigest();assert sha(raw)==meta['checkpointSHA256']==audit['checkpointSHA256'];assert sha(decoded.rsplit(',"rows":',1)[1][:-1].encode())==meta['outcomeRowsSHA256'];assert sha((p/'manifest.json').read_bytes())==meta['manifestSHA256'];assert audit['status']=='passed'and audit['fullOutcomesVerified']==meta['outcomes']==1536 and audit['fixtureClusters']==meta['fixtures']==512
for k in ['sourceSHA256','harnessSHA256']:assert audit[k]==m[k]==meta[k]
assert cp['fixtureIds']==[f['id']for f in m['fixtures'][(idx-1)*512:idx*512]];assert len({(r['fixture'],r['arm'])for r in cp['rows']})==1536
repo=Path(__file__).resolve().parents[1];q=json.loads((repo/'docs/verification/club-extreme-confirmation-2026-11-18/block-audit-qualification.json').read_text())
for k,file in [('driverSHA256','scripts/audit-confirmation-block.py'),('shardSHA256','scripts/audit-confirmation-block-shard.mjs'),('pinnedAuditSHA256','experiments/club-confirmation/audit.mjs')]:assert q[k]==audit[k]==sha((repo/file).read_bytes())
prefix='docs/verification/club-extreme-confirmation-2026-11-18/checkpoints/';pub=repo.parent/'.confirmation-publication';pub.mkdir(exist_ok=True);b64=base64.b64encode(raw).decode();(pub/(name+'.b64')).write_text(b64);blob=hashlib.sha1(b'blob '+str(len(raw)).encode()+b'\0'+raw).hexdigest();sidecar={'status':'passed','compactOutcomeCheckpoint':meta,'fullRetainedLedgerReadback':audit,'gitBlobSHA':blob,'bytes':len(raw),'classification':'Fresh scientific compact outcome data and full retained-ledger audit receipt, before next block advances'};payload={'blockIndex':idx,'base64File':str(pub/(name+'.b64')),'characters':len(b64),'blobSHA':blob,'remoteDataPath':prefix+name+'.json.gz','remoteMetadataPath':prefix+name+'.json','metadata':meta,'sidecar':sidecar,'studyDirectory':str(p)};(pub/(name+'.prepared.json')).write_text(json.dumps(payload,indent=2)+'\n');print(json.dumps({'prepared':idx,'outcomes':meta['outcomes'],'bytes':len(raw),'payload':str(pub/(name+'.prepared.json'))}))
